    const shouldAutoDismiss = options.autoDismiss !== false
      && (explicitMs !== null ? explicitMs > 0 : safeTone !== 'danger');
    if (shouldAutoDismiss) {
      window.setTimeout(() => dismiss(toast), explicitMs !== null ? explicitMs : AUTO_DISMISS_MS);
    }

